+func (w *worker) begin(id uint64) bool {
+	w.mu.Lock()
+	defer w.mu.Unlock()
+	if w.cancelled[id] {
+		delete(w.cancelled, id)
+		return false
+	}
+	w.running = id
+	w.stop.Store(false)
+	return true
+}
+
+func (w *worker) finished(id uint64) {
+	w.mu.Lock()
+	defer w.mu.Unlock()
+	w.running = 0
+	delete(w.cancelled, id)
+}
+
+func (w *worker) complete(req protocol.Request) protocol.Response {
